package hu.synostream.android;
import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Bounded EBML metadata inspection. Same-length header edits preserve all byte ranges and encoded samples. */
public final class MatroskaAudio {
    public static final int MAX_HEADER=4*1024*1024;
    public static final class Track {public int number,ordinal;public String language="und",codec="";int defaultOffset=-1;int enabledOffset=-1,replacementStart=-1,replacementLength;public String label(){return "Szám "+(ordinal>0?ordinal:number)+": "+language+" ("+codec.replace("A_","").toLowerCase(Locale.ROOT)+")";}}
    private static final class Crc {int data,start,end,skipStart,skipEnd;}
    private static final class Tracks extends ArrayList<Track> {byte[] header;boolean segmentCrc,allowEnable=true;List<Crc> crcs=new ArrayList<>();}
    private static void crc(Tracks tracks,Element field,int parentStart,int parentEnd){if(field.size!=4)return;Crc c=new Crc();c.data=field.data;c.start=parentStart;c.end=parentEnd;c.skipStart=field.start;c.skipEnd=field.end;tracks.crcs.add(c);}
    private static final class Element {long id,size;int start,data,end;}
    private static Element element(byte[] b,int p,int limit)throws IOException{if(p>=limit)throw new EOFException();Element e=new Element();e.start=p;int n=width(b[p]&255,4);e.id=0;for(int i=0;i<n;i++){if(p>=limit)throw new EOFException();e.id=(e.id<<8)|(b[p++]&255);}if(p>=limit)throw new EOFException();n=width(b[p]&255,8);long value=b[p++]&((1<<(8-n))-1);boolean unknown=value==((1<<(8-n))-1);for(int i=1;i<n;i++){if(p>=limit)throw new EOFException();int v=b[p++]&255;value=(value<<8)|v;unknown&=v==255;}e.data=p;e.size=unknown?Long.MAX_VALUE:value;long end=unknown?limit:(long)p+value;e.end=(int)Math.min(limit,end);return e;}
    private static int width(int first,int max)throws IOException{for(int n=1;n<=max;n++)if((first&(1<<(8-n)))!=0)return n;throw new IOException("Hibás EBML-fejléc.");}
    private static long unsigned(byte[] b,Element e){if(e.size<1||e.size>8||e.data+e.size>b.length)return -1;long n=0;for(int p=e.data;p<e.data+e.size;p++)n=(n<<8)|(b[p]&255);return n;}
    public static List<Track> inspect(byte[] b)throws IOException{Tracks tracks=new Tracks();tracks.header=b.clone();int pos=0;boolean segment=false;while(pos<b.length){Element e;try{e=element(b,pos,b.length);}catch(EOFException end){break;}if(!segment&&e.id==0x1a45dfa3L){tracks.allowEnable=false;int h=e.data;while(h<e.end){Element field=element(b,h,e.end);if(field.id==0x4287&&unsigned(b,field)>=2)tracks.allowEnable=true;h=field.end;}}if(!segment&&e.id==0x18538067L){segment=true;pos=e.data;continue;}if(segment&&e.id==0xbf)tracks.segmentCrc=true;if(segment&&e.id==0x1654ae6bL){if(e.size>b.length-e.data)throw new IOException("A hangsávlista nem fér a fejlécbe.");int p=e.data;while(p<e.end){Element entry=element(b,p,e.end);if(entry.size>e.end-entry.data)throw new IOException("Hiányos TrackEntry.");if(entry.id==0xbf)crc(tracks,entry,e.data,e.end);if(entry.id==0xae){Track track=new Track();long type=-1;int q=entry.data;while(q<entry.end){Element field=element(b,q,entry.end);if(field.size>entry.end-field.data)throw new IOException("Hiányos hangsávadat.");if(field.id==0xbf)crc(tracks,field,entry.data,entry.end);if(field.id==0xd7)track.number=(int)unsigned(b,field);else if(field.id==0x83)type=unsigned(b,field);else if(field.id==0x86)track.codec=new String(b,field.data,(int)field.size,StandardCharsets.UTF_8);else if(field.id==0x22b59c||field.id==0x22b59d)track.language=new String(b,field.data,(int)field.size,StandardCharsets.UTF_8);if(field.id==0xb9&&field.size==1)track.enabledOffset=field.data;if(field.id==0x88&&field.size==1)track.defaultOffset=field.data;if((field.id==0x22b59c||field.id==0x22b59d||field.id==0x536e||field.id==0x258688||field.id==0xec)&&field.end-field.start>=5){track.replacementStart=field.start;track.replacementLength=field.end-field.start;}q=field.end;}if(type==2&&track.number>0){for(Track existing:tracks)if(existing.number==track.number)throw new IOException("Ismétlődő hangsávazonosító.");track.ordinal=tracks.size()+1;tracks.add(track);}}p=entry.end;}return tracks;}if(e.size==Long.MAX_VALUE||e.size>b.length-e.data)break;pos=e.end;}return tracks;}
    public static Map<Long,Byte> select(List<Track> tracks,int number){if(tracks.stream().noneMatch(t->t.number==number))throw new IllegalArgumentException("Ismeretlen hangsáv.");if(tracks instanceof Tracks&&((Tracks)tracks).segmentCrc)return Map.of();Map<Long,Byte> patch=new TreeMap<>();for(Track track:tracks){boolean enable=!(tracks instanceof Tracks)||((Tracks)tracks).allowEnable;int enabled=track.number==number?1:0;if(track.defaultOffset>=0)patch.put((long)track.defaultOffset,(byte)enabled);int offset=enable?track.enabledOffset:track.defaultOffset;if(offset>=0){patch.put((long)offset,(byte)enabled);continue;}if(enabled==1)continue;if(track.replacementStart<0)return Map.of();int p=track.replacementStart;patch.put((long)p++,(byte)(enable?0xb9:0x88));patch.put((long)p++,(byte)0x81);patch.put((long)p++,(byte)0);int rest=track.replacementLength-3;patch.put((long)p++,(byte)0xec);int width=1;while(rest-1-width>((1L<<(7*width))-2))width++;int payload=rest-1-width;if(payload<0)return Map.of();long encoded=(1L<<(7*width))|payload;for(int i=width-1;i>=0;i--)patch.put((long)p++,(byte)(encoded>>(8*i)));for(int i=0;i<payload;i++)patch.put((long)p++,(byte)0);}if(tracks instanceof Tracks){Tracks source=(Tracks)tracks;byte[] header=source.header.clone();patch(header,header.length,0,patch);source.crcs.sort(Comparator.comparingInt(c->c.end-c.start));for(Crc c:source.crcs){java.util.zip.CRC32 sum=new java.util.zip.CRC32();sum.update(header,c.start,c.skipStart-c.start);sum.update(header,c.skipEnd,c.end-c.skipEnd);long value=sum.getValue();for(int i=0;i<4;i++){byte v=(byte)(value>>(8*i));patch.put((long)c.data+i,v);header[c.data+i]=v;}}}return patch;}
    public static void patch(byte[] bytes,int length,long offset,Map<Long,Byte> changes){for(var item:changes.entrySet()){long at=item.getKey()-offset;if(at>=0&&at<length)bytes[(int)at]=item.getValue();}}
}
